{
  "verdict": "request_changes",
  "summary": "Candidate implementation does not shift a weekend start to Monday when adding zero business days, violating the contract.",
  "findings": [
    {
      "finding_id": "F001",
      "file": "candidate.py",
      "line_start": 5,
      "line_end": 6,
      "severity": "high",
      "description": "When n == 0, the function returns the original start date without moving a weekend start to the following Monday, contradicting the requirement that n == 0 returns the following Monday on a weekend.",
      "evidence": "For example, add_business_days(date(2026, 11, 5), 0) should return date(2026, 11, 7) but currently returns date(2026, 11, 5)."
    }
  ]
}
